package registry

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

// snapshotJSON is the committed subset of the official ACP registry. It is
// regenerated by hand with internal/registry/cmd/snapshot; nothing fetches the
// registry at run time.
//
//go:embed snapshot.json
var snapshotJSON []byte

// SnapshotIDs are the registry agents the committed snapshot keeps. The
// generator filters on this list and the snapshot test checks against it, so
// the two cannot drift apart.
var SnapshotIDs = []string{
	"qwen-code",
	"kimi",
	"codebuddy-code",
	"minimax-code",
	"qoder",
	"opencode",
	"glm-acp-agent",
	"claude-acp",
	"codex-acp",
	"gemini",
}

// doc is the registry file itself: a format version plus the agent entries.
type doc struct {
	Version string  `json:"version"`
	Agents  []entry `json:"agents"`
}

// entry is one agent preset. Only the fields Ferry acts on are named; the
// generator copies the entries through verbatim, so the snapshot keeps every
// field the official registry publishes.
type entry struct {
	ID           string            `json:"id"`
	Name         string            `json:"name"`
	Version      string            `json:"version"`
	Description  string            `json:"description"`
	Env          map[string]string `json:"env,omitempty"`
	Distribution distribution      `json:"distribution"`
}

// distribution lists the ways an agent can be launched. An entry carries one
// or more of them; which one Ferry picks is decided by planRegistry.
type distribution struct {
	NPX    *pkgDist              `json:"npx,omitempty"`
	UVX    *pkgDist              `json:"uvx,omitempty"`
	Binary map[string]binaryDist `json:"binary,omitempty"`
}

// pkgDist is an npx or uvx package. Package already carries the version.
type pkgDist struct {
	Package string            `json:"package"`
	Args    []string          `json:"args,omitempty"`
	Env     map[string]string `json:"env,omitempty"`
}

// binaryDist is a downloadable archive for one platform key, such as
// "darwin-aarch64". Cmd is relative to the extracted directory.
type binaryDist struct {
	Archive string            `json:"archive"`
	Cmd     string            `json:"cmd"`
	Args    []string          `json:"args,omitempty"`
	SHA256  string            `json:"sha256"`
	Env     map[string]string `json:"env,omitempty"`
}

// parseSnapshot reads a registry document and indexes its agents by id.
func parseSnapshot(b []byte) (map[string]entry, error) {
	var d doc
	if err := json.Unmarshal(b, &d); err != nil {
		return nil, fmt.Errorf("registry: parse snapshot: %w", err)
	}
	if len(d.Agents) == 0 {
		return nil, fmt.Errorf("registry: parse snapshot: no agents")
	}

	byID := make(map[string]entry, len(d.Agents))
	for _, a := range d.Agents {
		if a.ID == "" {
			return nil, fmt.Errorf("registry: parse snapshot: an agent has no id")
		}
		byID[a.ID] = a
	}
	return byID, nil
}
